content.content:
1	:root {
2	  --bg-primary: #0d0d0d;
3	  --bg-secondary: #1a1a2e;
4	  --bg-tertiary: #16213e;
5	  --bg-window: rgba(18,18,18,0.85);
6	  --navbar-bg: rgba(18,18,18,0.85);
7	  --accent-primary: #e94560;
8	  --accent-secondary: #7b2cbf;
9	  --accent-tertiary: #00d9ff;
10	  --text-primary: #eaeaea;
11	  --text-muted: #888;
12	  --text-dim: #555;
13	  --border-pixel-width: 3px;
14	  --shadow-offset: 4px;
15	  --scanline-opacity: 0.04;
16	  --glow-intensity: 10px;
17	  --gap-xs: 0.25rem;
18	  --gap-sm: 0.5rem;
19	  --gap-md: 1rem;
20	  --gap-lg: 1.5rem;
21	  --gap-xl: 2rem;
22	  --header-height: 2.5rem;
23	  --window-border-radius: 0;
24	  --container-max-width: 1200px;
25	}
26	
27	.light-mode {
28	  --bg-primary: #f5f5f5;
29	  --bg-secondary: #e8e8e8;
30	  --bg-tertiary: #ddd;
31	  --bg-window: #fff;
32	  --navbar-bg: rgba(248,248,248,0.92);
33	  --text-primary: #1a1a1a;
34	  --text-muted: #666;
35	  --text-dim: #999;
36	  --scanline-opacity: 0.02;
37	}
38	
39	.light-mode .icon-grid__item svg {
40	  filter: grayscale(20%) brightness(0.7);
41	  color: var(--accent-primary);
42	}
43	.light-mode .icon-grid__item:hover svg {
44	  filter: grayscale(0%) brightness(1);
45	}
46	.light-mode .design-tooltip,
47	.light-mode .tech-tooltip,
48	.light-mode .toast-notif {
49	  color: #d0d0d0;
50	  background: rgba(20, 20, 40, 0.95);
51	}
52	.light-mode .toast-notif {
53	  border-color: rgba(233, 69, 96, 0.3);
54	}
55	
56	*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
57	
58	html {
59	  font-size: 16px;
60	  scroll-behavior: smooth;
61	}
62	
63	body {
64	  font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;
65	  background: var(--bg-primary);
66	  color: var(--text-primary);
67	  min-height: 100vh;
68	  line-height: 1.6;
69	  overflow-x: hidden;
70	  position: relative;
71	}
72	
73	.animated-bg {
74	  position: fixed;
75	  top: 0; left: 0;
76	  width: 100vw; height: 100vh;
77	  z-index: 0;
78	  overflow: hidden;
79	  background-size: cover;
80	  background-position: center;
81	  background-repeat: no-repeat;
82	  transition: background-image 1s ease;
83	}
84	
85	.animated-bg::after {
86	  content: '';
87	  position: absolute;
88	  inset: 0;
89	  background: linear-gradient(135deg, rgba(13,13,13,0.30) 0%, rgba(26,26,46,0.25) 100%);
90	  pointer-events: none;
91	}
92	
93	.crt-overlay {
94	  position: fixed;
95	  top: 0; left: 0;
96	  width: 100vw; height: 100vh;
97	  pointer-events: none;
98	  z-index: 99999;
99	  background: repeating-linear-gradient(
100	    transparent 0px, rgba(0,0,0,var(--scanline-opacity)) 1px, transparent 2px, transparent 4px
101	  );
102	  animation: scanlines-scroll 20s linear infinite;
103	}
104	
105	@keyframes scanlines-scroll {
106	  0% { background-position: 0 0; }
107	  100% { background-position: 0 100px; }
108	}
109	
110	h1, h2, h3, h4, h5, h6 { font-weight: 700; line-height: 1.2; }
111	h1 { font-size: 2rem; }
112	h2 { font-size: 1.5rem; }
113	h3 { font-size: 1.25rem; }
114	p { font-size: 1rem; color: var(--text-muted); }
115	
116	a {
117	  color: var(--accent-primary);
118	  text-decoration: none;
119	  transition: all 0.2s ease;
120	}
121	a:hover {
122	  color: var(--accent-tertiary);
123	  text-shadow: 0 0 8px var(--accent-tertiary);
124	}
125	
126	code, pre {
127	  font-family: inherit;
128	  background: var(--bg-tertiary);
129	  padding: 0.1em 0.3em;
130	  border-radius: 2px;
131	}
132	
133	.glow-text {
134	  text-shadow: 0 0 5px var(--accent-primary), 0 0 10px var(--accent-primary), 0 0 20px var(--accent-primary);
135	}
136	
137	::selection { background: var(--accent-primary); color: var(--bg-primary); }
138	
139	::-webkit-scrollbar { width: 8px; }
140	::-webkit-scrollbar-track { background: var(--bg-primary); }
141	::-webkit-scrollbar-thumb { background: var(--accent-secondary); border: 1px solid var(--bg-primary); }
142	::-webkit-scrollbar-thumb:hover { background: var(--accent-primary); }
143	
144	/* Window */
145	.window {
146	  background: var(--bg-window);
147	  backdrop-filter: blur(6px);
148	  -webkit-backdrop-filter: blur(6px);
149	  border: var(--border-pixel-width) solid var(--accent-primary);
150	  box-shadow: var(--shadow-offset) var(--shadow-offset) 0 var(--accent-secondary);
151	  position: relative;
152	  overflow: hidden;
153	  transition: transform 0.3s ease, filter 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
154	  cursor: pointer;
155	  height: 100%;
156	}
157	
158	.window:hover {
159	  animation: window-pop 0.3s ease forwards;
160	  box-shadow: 0 0 50px rgba(233,69,96,0.6), 0 0 100px rgba(233,69,96,0.25), 0 0 40px var(--accent-tertiary);
161	  border-color: var(--accent-tertiary);
162	}
163	
164	.window::before {
165	  content: '';
166	  position: absolute;
167	  top: 0; left: -100%;
168	  width: 50%; height: 100%;
169	  background: linear-gradient(90deg, transparent, rgba(0,217,255,0.3), transparent);
170	  transform: skewX(-25deg);
171	  transition: left 0.6s ease;
172	  pointer-events: none;
173	  z-index: 10;
174	}
175	.window:hover::before { left: 150%; }
176	
177	@keyframes window-pop {
178	  0% { transform: scale(1) rotate(0deg); }
179	  70% { transform: scale(1.07) rotate(2deg); }
180	  100% { transform: scale(1.05) rotate(1deg); }
181	}
182	
183	.modal-window {
184	  max-width: 600px;
185	  width: 90%;
186	  max-height: 85vh;
187	  overflow-y: auto;
188	  z-index: 1;
189	}
190	
191	.modal-window:hover {
192	  animation: none;
193	  transform: none;
194	}
195	
196	.window__titlebar {
197	  display: flex;
198	  align-items: center;
199	  gap: var(--gap-sm);
200	  padding: var(--gap-xs) var(--gap-sm);
201	  background: var(--accent-primary);
202	  color: var(--bg-primary);
203	  font-size: 0.85rem;
204	  font-weight: 700;
205	}
206	
207	.window__titlebar-dots { display: flex; gap: 4px; }
208	.window__titlebar-dot {
209	  width: 10px; height: 10px;
210	  border: 2px solid var(--bg-primary);
211	  background: transparent;
212	}
213	.window__titlebar-dot--close { background: var(--bg-primary); }
214	
215	.window__content { padding: var(--gap-md); }
216	
217	/* Buttons */
218	.btn {
219	  display: inline-flex;
220	  align-items: center;
221	  gap: var(--gap-sm);
222	  padding: var(--gap-sm) var(--gap-md);
223	  font-family: inherit;
224	  font-size: 0.9rem;
225	  font-weight: 700;
226	  border: 2px solid var(--accent-primary);
227	  background: transparent;
228	  color: var(--accent-primary);
229	  cursor: pointer;
230	  transition: all 0.3s ease;
231	}
232	.btn:hover {
233	  background: var(--accent-primary);
234	  color: var(--bg-primary);
235	  box-shadow: 0 0 20px var(--accent-primary), 0 0 40px rgba(233,69,96,0.5);
236	  transform: translateY(-2px);
237	}
238	.btn--filled { background: var(--accent-primary); color: var(--bg-primary); }
239	.btn--filled:hover {
240	  background: transparent;
241	  color: var(--accent-primary);
242	  box-shadow: 0 0 20px var(--accent-primary), inset 0 0 20px rgba(233,69,96,0.3);
243	}
244	
245	.tag {
246	  display: inline-block;
247	  padding: 0.2rem 0.5rem;
248	  font-size: 0.75rem;
249	  background: var(--bg-tertiary);
250	  border: 1px solid var(--accent-secondary);
251	  color: var(--accent-tertiary);
252	}
253	
254	.avatar {
255	  width: 80px; height: 80px;
256	  border: var(--border-pixel-width) solid var(--accent-primary);
257	  box-shadow: 3px 3px 0 var(--accent-secondary);
258	  image-rendering: pixelated;
259	  object-fit: cover;
260	}
261	
262	.avatar-wrapper {
263	  position: relative;
264	  width: 100px;
265	  height: 100px;
266	  display: flex;
267	  align-items: center;
268	  justify-content: center;
269	}
270	
271	.avatar-img {
272	  filter: blur(6px) grayscale(0.3);
273	  transition: filter 0.3s, opacity 0.3s;
274	  position: relative;
275	  z-index: 2;
276	  width: 100px;
277	  height: 100px;
278	  border-radius: 8px;
279	  object-fit: cover;
280	}
281	
282	.avatar-img.avatar-glitch {
283	  filter: blur(2px) grayscale(0.5) contrast(1.3);
284	  opacity: 0.6;
285	}
286	
287	.avatar-dots {
288	  position: absolute;
289	  inset: 0;
290	  display: flex;
291	  align-items: center;
292	  justify-content: center;
293	  font-size: 1.5rem;
294	  letter-spacing: 4px;
295	  color: var(--accent-tertiary);
296	  z-index: 3;
297	  pointer-events: none;
298	  text-shadow: 0 0 10px var(--accent-tertiary), 0 0 20px var(--accent-tertiary);
299	  animation: dots-pulse 2s ease-in-out infinite;
300	}
301	
302	@keyframes dots-pulse {
303	  0%, 100% { opacity: 0.4; }
304	  50% { opacity: 1; }
305	}
306	
307	.avatar-glitch-layers {
308	  position: absolute;
309	  inset: 0;
310	  z-index: 1;
311	  pointer-events: none;
312	  opacity: 0;
313	  transition: opacity 0.2s;
314	}
315	
316	.avatar-glitch-layers.active {
317	  opacity: 1;
318	}
319	
320	.glitch-layer {
321	  position: absolute;
322	  inset: 0;
323	  background-size: cover;
324	  background-position: center;
325	  background-repeat: no-repeat;
326	  mix-blend-mode: screen;
327	  opacity: 0.4;
328	}
329	
330	.glitch-layer--r {
331	  animation: glitch-shift-r 0.3s infinite;
332	  background-color: rgba(255,0,0,0.3);
333	  background-blend-mode: multiply;
334	}
335	
336	.glitch-layer--g {
337	  animation: glitch-shift-g 0.2s infinite;
338	  background-color: rgba(0,255,0,0.3);
339	  background-blend-mode: multiply;
340	}
341	
342	.glitch-layer--b {
343	  animation: glitch-shift-b 0.25s infinite;
344	  background-color: rgba(0,0,255,0.3);
345	  background-blend-mode: multiply;
346	}
347	
348	@keyframes glitch-shift-r {
349	  0% { transform: translate(0); }
350	  20% { transform: translate(-3px, 1px); }
351	  40% { transform: translate(2px, -1px); }
352	  60% { transform: translate(-1px, 2px); }
353	  80% { transform: translate(3px, -2px); }
354	  100% { transform: translate(0); }
355	}
356	
357	@keyframes glitch-shift-g {
358	  0% { transform: translate(0); }
359	  20% { transform: translate(2px, -2px); }
360	  40% { transform: translate(-2px, 1px); }
361	  60% { transform: translate(3px, 2px); }
362	  80% { transform: translate(-1px, -1px); }
363	  100% { transform: translate(0); }
364	}
365	
366	@keyframes glitch-shift-b {
367	  0% { transform: translate(0); }
368	  20% { transform: translate(-2px, -1px); }
369	  40% { transform: translate(1px, 2px); }
370	  60% { transform: translate(-3px, -2px); }
371	  80% { transform: translate(2px, 1px); }
372	  100% { transform: translate(0); }
373	}
374	
375	.avatar--rounded {
376	  width: 72px; height: 72px;
377	  border-radius: 50%;
378	  border: 2px solid var(--accent-primary);
379	  box-shadow: 3px 3px 0 var(--accent-secondary);
380	  object-fit: cover;
381	}
382	
383	.terminal-line {
384	  display: flex;
385	  gap: var(--gap-sm);
386	  font-size: 0.9rem;
387	  margin-bottom: var(--gap-xs);
388	}
389	.terminal-line__prompt { color: var(--accent-tertiary); }
390	.terminal-line__cmd { color: var(--text-primary); }
391	.terminal-line__output { color: var(--text-muted); padding-left: 1.5rem; }
392	
393	.icon-grid {
394	  display: flex;
395	  flex-wrap: wrap;
396	  gap: var(--gap-md);
397	  justify-content: center;
398	}
399	
400	.icon-grid__item {
401	  display: flex;
402	  flex-direction: column;
403	  align-items: center;
404	  gap: var(--gap-xs);
405	  padding: var(--gap-md);
406	  width: 100px;
407	  cursor: pointer;
408	  transition: all 0.3s ease;
409	  position: relative;
410	}
411	.icon-grid__item:hover {
412	  transform: scale(1.2) translateY(-5px);
413	  filter: drop-shadow(0 0 15px var(--accent-tertiary));
414	}
415	.icon-grid__item svg {
416	  color: var(--accent-tertiary);
417	  filter: grayscale(100%) brightness(1.5);
418	  transition: filter 0.3s ease, transform 0.3s ease, color 0.3s ease;
419	}
420	.icon-grid__item:hover svg {
421	  color: var(--accent-primary);
422	  filter: grayscale(0%) brightness(1) drop-shadow(0 0 10px currentColor);
423	  transform: rotate(5deg);
424	}
425	.icon-grid__label {
426	  font-size: 0.75rem;
427	  color: var(--text-muted);
428	  text-align: center;
429	  transition: color 0.3s ease, text-shadow 0.3s ease;
430	}
431	.icon-grid__item:hover .icon-grid__label {
432	  color: var(--accent-tertiary);
433	  text-shadow: 0 0 8px var(--accent-tertiary);
434	}
435	
436	.tech-hint {
437	  text-align: center;
438	  color: var(--text-dim);
439	  font-size: 0.8rem;
440	  margin-top: var(--gap-md);
441	}
442	
443	/* Tech popup */
444	.tech-popup {
445	  position: fixed;
446	  z-index: 9998;
447	  max-width: 320px;
448	  padding: 0.75rem 1rem;
449	  background: rgba(18,18,18,0.95);
450	  backdrop-filter: blur(12px);
451	  border: 1px solid var(--accent-tertiary);
452	  color: var(--text-primary);
453	  font-size: 0.8rem;
454	  line-height: 1.5;
455	  pointer-events: none;
456	  display: none;
457	}
458	
459	/* Modal overlay */
460	.modal-overlay {
461	  position: fixed;
462	  inset: 0;
463	  z-index: 9999;
464	  display: flex;
465	  justify-content: center;
466	  align-items: center;
467	  opacity: 0;
468	  pointer-events: none;
469	  transition: opacity 0.3s ease;
470	}
471	
472	.modal-overlay.active {
473	  opacity: 1;
474	  pointer-events: auto;
475	}
476	
477	.modal-backdrop {
478	  position: absolute;
479	  inset: 0;
480	  background: rgba(0,0,0,0.85);
481	}
482	
483	.modal-close-btn {
484	  margin-left: auto;
485	  background: transparent;
486	  border: 1px solid var(--bg-primary);
487	  color: var(--bg-primary);
488	  font-family: inherit;
489	  font-size: 0.8rem;
490	  padding: 0.1rem 0.4rem;
491	  cursor: pointer;
492	  transition: all 0.2s;
493	}
494	.modal-close-btn:hover { background: var(--bg-primary); color: var(--accent-primary); }
495	
496	/* Hero HUD */
497	.hero-hud {
498	  text-align: center;
499	  color: var(--text-dim);
500	  font-size: 0.8rem;
501	  margin-top: var(--gap-md);
502	  font-family: inherit;
503	}
504	.hud-key { color: var(--accent-tertiary); font-weight: 700; }
505	.hud-meta { color: var(--text-muted); }
506	.hud-sep { margin: 0 var(--gap-xs); color: var(--text-dim); }
507	
508	/* About grid */
509	.about-grid {
510	  display: grid;
511	  grid-template-columns: auto 1fr;
512	  gap: var(--gap-xs) var(--gap-md);
513	  margin-bottom: var(--gap-md);
514	  font-size: 0.9rem;
515	}
516	.about-grid__label { color: var(--accent-primary); font-weight: 700; }
517	.about-grid__value { color: var(--text-primary); }
518	
519	.about-bio {
520	  color: var(--text-muted);
521	  font-size: 0.9rem;
522	  line-height: 1.7;
523	}
524	
525	.section__title {
526	  color: var(--accent-primary);
527	  font-size: 1.1rem;
528	  margin-bottom: var(--gap-lg);
529	  text-align: center;
530	}
531	
532	/* Tiling container for projects */
533	.tiling-container {
534	  display: grid;
535	  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
536	  gap: var(--gap-lg);
537	}
538	
539	/* Project cards: glow but no tilt */
540	.tiling-container .window:hover {
541	  animation: none;
542	  transform: scale(1.03);
543	}
544	
545	/* Toast notification */
546	.toast-notif {
547	  position: fixed;
548	  bottom: 4rem;
549	  left: 50%;
550	  transform: translateX(-50%) translateY(20px);
551	  z-index: 9998;
552	  padding: 0.6rem 1.2rem;
553	  border-radius: 9999px;
554	  background: rgba(7, 7, 26, 0.9);
555	  backdrop-filter: blur(12px);
556	  border: 1px solid rgba(244, 114, 182, 0.2);
557	  font-family: 'Space Grotesk', sans-serif;
558	  font-size: 0.8rem;
559	  color: #d0d0d0;
560	  opacity: 0;
561	  pointer-events: none;
562	  transition: all 0.4s ease;
563	  white-space: nowrap;
564	}
565	.toast-notif.show { opacity: 1; transform: translateX(-50%) translateY(0); }
566	
567	/* Floating phrases */
568	.floating-phrase {
569	  position: fixed;
570	  bottom: 3.5rem;
571	  right: 1.5rem;
572	  z-index: 9997;
573	  font-size: 0.75rem;
574	  color: var(--text-dim);
575	  font-family: 'Space Grotesk', sans-serif;
576	  opacity: 0;
577	  transition: opacity 0.5s ease;
578	  pointer-events: none;
579	}
580	.floating-phrase.show { opacity: 1; }
581	
582	/* Noise overlay SVG */
583	.noise-overlay {
584	  position: fixed;
585	  inset: 0;
586	  z-index: 99997;
587	  pointer-events: none;
588	  mix-blend-mode: difference;
589	  opacity: 0.03;
590	}
591	
592	/* Header */
593	.header {
594	  position: fixed;
595	  top: 0; left: 0; right: 0;
596	  height: var(--header-height);
597	  background: rgba(13,13,13,0.7);
598	  backdrop-filter: blur(4px);
599	  border-bottom: 2px solid var(--accent-secondary);
600	  display: flex;
601	  justify-content: space-between;
602	  align-items: center;
603	  padding: 0 var(--gap-lg);
604	  z-index: 1000;
605	  font-size: 0.85rem;
606	}
607	.header__left { display: flex; align-items: center; gap: var(--gap-sm); }
608	.header__prompt { color: var(--accent-tertiary); }
609	.header__user { color: var(--accent-primary); }
610	.header__path { color: var(--text-muted); }
611	.header__right { display: flex; align-items: center; gap: var(--gap-lg); color: var(--text-dim); }
612	.header__right span { display: flex; align-items: center; gap: var(--gap-xs); }
613	.header-btn {
614	  background: transparent;
615	  border: 1px solid var(--text-dim);
616	  color: var(--text-muted);
617	  font-family: inherit;
618	  font-size: 0.8rem;
619	  padding: 0.1rem 0.4rem;
620	  cursor: pointer;
621	  transition: all 0.2s;
622	}
623	.header-btn:hover { border-color: var(--accent-tertiary); color: var(--accent-tertiary); }
624	.available-badge { display: flex; align-items: center; gap: var(--gap-xs); color: #33c08c; }
625	.available-dot {
626	  width: 8px; height: 8px;
627	  background: #33c08c;
628	  border-radius: 50%;
629	  animation: blink 1s step-end infinite;
630	}
631	@keyframes blink { 50% { opacity: 0; } }
632	
633	.mobile-menu-btn { display: none; }
634	
635	/* Footer */
636	
637	/* Hero code overlay */
638	.hero-code-overlay {
639	  position: absolute;
640	  inset: 0;
641	  overflow: hidden;
642	  pointer-events: none;
643	  z-index: 1;
644	}
645	.hero-code-line {
646	  position: absolute;
647	  font-size: 0.6rem;
648	  color: var(--accent-tertiary);
649	  opacity: 0.25;
650	  white-space: nowrap;
651	  animation: code-fade 4s ease forwards;
652	}
653	@keyframes code-fade {
